class InputReader {
private:
    bool isDispose;
    istream& sr;
    vector<string> buffer;
    int seek;

public:
    InputReader(istream& stream) : isDispose(false), sr(stream), seek(0) {}

    string NextString() {
        string result;
        getline(sr, result);
        return result;
    }

    int NextInt32() {
        return stoi(ReadNextToken());
    }

    long long NextInt64() {
        return stoll(ReadNextToken());
    }

    vector<int> ReadArrayOfInt32() {
        return ReadArray<int>([](const string& s) {
            return stoi(s);
        });
    }

    vector<long long> ReadArrayOfInt64() {
        return ReadArray<long long>([](const string& s) {
            return stoll(s);
        });
    }

    vector<string> NextSplitStrings() {
        string line = NextString();
        vector<string> res;
        stringstream ss(line);
        string token;
        while (ss >> token) {
            res.push_back(token);
        }
        return res;
    }

    template<typename T, typename F>
    vector<T> ReadArray(F func) {
        vector<string> parts = NextSplitStrings();
        vector<T> res;
        res.reserve(parts.size());
        for (auto& s : parts) {
            res.push_back(func(s));
        }
        return res;
    }

