    vector<T> ReadArrayFromString(F func, const string& str) {
        vector<T> res;
        stringstream ss(str);
        string token;
        while (ss >> token) {
            res.push_back(func(token));
        }
        return res;
    }

private:
    string ReadNextToken() {
        if (buffer.empty() || seek == (int)buffer.size()) {
            seek = 0;
            buffer = NextSplitStrings();
        }
        return buffer[seek++];
    }
};

